soup = BeautifulSoup(LIBRARY.read_text(encoding="utf-8"), "html.parser")

changed = 0
missing = []

for folder_id, svg_html in SVG_MAP.items():
    folder = soup.find("details", id=folder_id)
    if folder is None:
        missing.append(folder_id)
        continue

    icon = folder.select_one("summary .folder-icon")
    if icon is None:
        missing.append(folder_id)
        continue

    new_svg = BeautifulSoup(svg_html, "html.parser").find("svg")
    old_svg = icon.find("svg")

    if old_svg is not None:
        old_svg.replace_with(new_svg)
    else:
        icon.insert(0, new_svg)

    icon["data-icon-v"] = "110"
    changed += 1

LIBRARY.write_text(str(soup), encoding="utf-8")

print(f"Icons replaced: {changed}")
print(f"Missing mappings in current Library: {len(missing)}")
if missing:
    print("\n".join(missing))
